import{GYM12}from'../gym12-native/registration.mjs';import{gym12Actors}from'../gym12-native/visual-state.mjs';import{gym12Facing}from'../gym12-native/native-gym12-authority.mjs';
// Reject-only owner projection. It never changes the canonical battle result or actor pose.
export function gym12ActionCandidates(no,pose){if(!pose)return[];return GYM12[no].points.filter(r=>{const anchor=r.kind==='trainer'?gym12Actors(no,pose.state).find(a=>a.id===r.sourceRow.trainerId).foot:r.anchor;return r.approachRows[pose.state]?.some(([y,a,b])=>pose.foot[1]===y&&pose.foot[0]>=a&&pose.foot[0]<b)&&Math.abs(pose.foot[0]-anchor[0])+Math.abs(pose.foot[1]-anchor[1])<=r.readL1&&pose.facing===gym12Facing(r,pose.foot,anchor)})}
export function gym12PostActionSafe(no,pose,safe){if(!pose||typeof safe!=='function'||!safe(pose.foot,pose.state))return false;return gym12ActionCandidates(no,pose).every(r=>{const id=r.sourceRow.trainerId,bit=id===`GYM_0${no}_SUB_01`?1:id===`GYM_0${no}_SUB_02`?2:0;return !bit||safe(pose.foot,pose.state|bit)})}
